import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"

// ============================================
// Types & constants
// ============================================
interface PageProps {
  data: {
    photos: {
      nodes: {
        childImageSharp: {
          original: { width: number; height: number }
          full: IGatsbyImageData
        }
      }[]
    }
  }
}

type Tool = 'draw' | 'eraser' | 'eyedropper' | 'smudge'
type BlendMode = 'source-over' | 'multiply' | 'screen' | 'overlay'

const LINE_WIDTHS = [2, 4, 8, 14, 24]
const SWATCH_COLOURS = [
  '#E8F4F8', // white
  '#9E0B0F', // red
  '#F26522', // orange
  '#FFF200', // yellow
  '#39B54A', // green
  '#00AEF0', // blue
  '#ED008C', // pink
  '#440E62', // purple
]

const BLEND_MODES: { value: BlendMode; label: string }[] = [
  { value: 'source-over', label: 'Normal' },
  { value: 'multiply', label: 'Multiply' },
  { value: 'screen', label: 'Screen' },
  { value: 'overlay', label: 'Overlay' },
]

const MAX_HISTORY = 30

// ============================================
// Component
// ============================================
const ParticleDrawPage: React.FC<PageProps> = ({ data }) => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const drawingRef = React.useRef(false)
  const pointsRef = React.useRef<{ x: number; y: number }[]>([])
  const colourRef = React.useRef(SWATCH_COLOURS[0])
  const widthRef = React.useRef(LINE_WIDTHS[1])
  const opacityRef = React.useRef(1)
  const toolRef = React.useRef<Tool>('draw')
  const blendRef = React.useRef<BlendMode>('source-over')
  const bgImageRef = React.useRef<HTMLImageElement | null>(null)
  const bgCanvasRef = React.useRef<HTMLCanvasElement | null>(null) // offscreen canvas with just the photo
  const historyRef = React.useRef<ImageData[]>([])
  const historyIndexRef = React.useRef(-1)
  const smudgeBufferRef = React.useRef<ImageData | null>(null)

  const [activeColour, setActiveColour] = React.useState(SWATCH_COLOURS[0])
  const [activeWidth, setActiveWidth] = React.useState(LINE_WIDTHS[1])
  const [activeOpacity, setActiveOpacity] = React.useState(1)
  const [activeTool, setActiveTool] = React.useState<Tool>('draw')
  const [activeBlend, setActiveBlend] = React.useState<BlendMode>('source-over')
  const [photoLoaded, setPhotoLoaded] = React.useState(false)
  const [photoKey, setPhotoKey] = React.useState(0)
  const [canUndo, setCanUndo] = React.useState(false)
  const [canRedo, setCanRedo] = React.useState(false)

  const handleColourChange = (colour: string) => {
    colourRef.current = colour
    setActiveColour(colour)
    // Switch back to draw tool when picking a colour
    if (toolRef.current === 'eyedropper') {
      toolRef.current = 'draw'
      setActiveTool('draw')
    }
  }

  const handleWidthChange = (width: number) => {
    widthRef.current = width
    setActiveWidth(width)
  }

  const handleToolChange = (tool: Tool) => {
    toolRef.current = tool
    setActiveTool(tool)
  }

  const handleBlendChange = (mode: BlendMode) => {
    blendRef.current = mode
    setActiveBlend(mode)
  }

  // Push current canvas state to history
  const pushHistory = (ctx: CanvasRenderingContext2D, canvas: HTMLCanvasElement) => {
    const snapshot = ctx.getImageData(0, 0, canvas.width, canvas.height)
    const idx = historyIndexRef.current
    // Discard any redo states ahead of current position
    historyRef.current = historyRef.current.slice(0, idx + 1)
    historyRef.current.push(snapshot)
    // Cap history size
    if (historyRef.current.length > MAX_HISTORY) {
      historyRef.current.shift()
    }
    historyIndexRef.current = historyRef.current.length - 1
    setCanUndo(historyIndexRef.current > 0)
    setCanRedo(false)
  }

  const handleUndo = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    if (historyIndexRef.current <= 0) return

    historyIndexRef.current--
    const snapshot = historyRef.current[historyIndexRef.current]
    ctx.putImageData(snapshot, 0, 0)
    setCanUndo(historyIndexRef.current > 0)
    setCanRedo(true)
  }

  const handleRedo = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    if (historyIndexRef.current >= historyRef.current.length - 1) return

    historyIndexRef.current++
    const snapshot = historyRef.current[historyIndexRef.current]
    ctx.putImageData(snapshot, 0, 0)
    setCanUndo(true)
    setCanRedo(historyIndexRef.current < historyRef.current.length - 1)
  }

  // Draw the background photo onto a canvas
  const drawBackground = React.useCallback((ctx: CanvasRenderingContext2D, img: HTMLImageElement, w: number, h: number, dpr: number) => {
    ctx.fillStyle = '#0A192F'
    ctx.fillRect(0, 0, w * dpr, h * dpr)

    ctx.save()
    ctx.scale(dpr, dpr)

    const imgRatio = img.naturalWidth / img.naturalHeight
    const canvasRatio = w / h
    let drawW: number, drawH: number, drawX: number, drawY: number
    if (imgRatio > canvasRatio) {
      drawW = w
      drawH = w / imgRatio
      drawX = 0
      drawY = (h - drawH) / 2
    } else {
      drawH = h
      drawW = h * imgRatio
      drawX = (w - drawW) / 2
      drawY = 0
    }

    ctx.drawImage(img, drawX, drawY, drawW, drawH)
    ctx.restore()
  }, [])

  const handleClear = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const dpr = window.devicePixelRatio || 1
    const { width, height } = wrapperRef.current!.getBoundingClientRect()

    ctx.clearRect(0, 0, canvas.width, canvas.height)
    if (bgImageRef.current) {
      drawBackground(ctx, bgImageRef.current, width, height, dpr)
    }
    pushHistory(ctx, canvas)
  }

  React.useEffect(() => {
    const canvas = canvasRef.current
    const wrapper = wrapperRef.current
    if (!canvas || !wrapper) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const dpr = window.devicePixelRatio || 1

    // Reset history for new photo
    historyRef.current = []
    historyIndexRef.current = -1
    setCanUndo(false)
    setCanRedo(false)

    // Pick a random photo
    const nodes = data.photos.nodes
    if (nodes.length === 0) return
    const pick = nodes[Math.floor(Math.random() * nodes.length)]
    const imageData = getImage(pick.childImageSharp.full)
    if (!imageData) return

    const imgSrc = imageData.images?.fallback?.src
    if (!imgSrc) return

    const resize = () => {
      const rect = wrapper.getBoundingClientRect()
      canvas.width = rect.width * dpr
      canvas.height = rect.height * dpr
      canvas.style.width = `${rect.width}px`
      canvas.style.height = `${rect.height}px`

      if (bgImageRef.current) {
        drawBackground(ctx, bgImageRef.current, rect.width, rect.height, dpr)

        // Also update the offscreen background canvas
        if (!bgCanvasRef.current) {
          bgCanvasRef.current = document.createElement('canvas')
        }
        bgCanvasRef.current.width = canvas.width
        bgCanvasRef.current.height = canvas.height
        const bgCtx = bgCanvasRef.current.getContext('2d')
        if (bgCtx) {
          drawBackground(bgCtx, bgImageRef.current, rect.width, rect.height, dpr)
        }
      }
    }

    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => {
      bgImageRef.current = img
      setPhotoLoaded(true)
      resize()
      // Save initial state to history
      pushHistory(ctx, canvas)
    }
    img.src = imgSrc

    resize()

    const ro = new ResizeObserver(resize)
    ro.observe(wrapper)

    // Drawing helpers
    const getPos = (e: MouseEvent | Touch) => {
      const rect = canvas.getBoundingClientRect()
      return { x: e.clientX - rect.left, y: e.clientY - rect.top }
    }

    // ---- Smooth stroke drawing ----
    const redrawStroke = () => {
      const pts = pointsRef.current
      if (pts.length < 2) return
      const tool = toolRef.current

      ctx.save()
      ctx.scale(dpr, dpr)
      ctx.beginPath()
      ctx.moveTo(pts[0].x, pts[0].y)

      for (let i = 1; i < pts.length - 1; i++) {
        const mx = (pts[i].x + pts[i + 1].x) / 2
        const my = (pts[i].y + pts[i + 1].y) / 2
        ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my)
      }
      const last = pts[pts.length - 1]
      ctx.lineTo(last.x, last.y)

      if (tool === 'eraser') {
        // Eraser: clip to stroke path and draw background through it
        ctx.lineWidth = widthRef.current
        ctx.lineCap = 'round'
        ctx.lineJoin = 'round'
        ctx.stroke() // invisible, just to define the path for clipping
        // Reset and use destination-out wouldn't work well, so instead
        // we restore the pre-stroke, then clip and draw background
        ctx.restore()

        // Re-do: restore snapshot, then clip to the stroke path and paint bg
        if (preStrokeSnapshot) {
          ctx.putImageData(preStrokeSnapshot, 0, 0)
        }
        ctx.save()
        ctx.scale(dpr, dpr)
        ctx.beginPath()
        ctx.moveTo(pts[0].x, pts[0].y)
        for (let i = 1; i < pts.length - 1; i++) {
          const mx = (pts[i].x + pts[i + 1].x) / 2
          const my = (pts[i].y + pts[i + 1].y) / 2
          ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my)
        }
        ctx.lineTo(last.x, last.y)
        ctx.lineWidth = widthRef.current
        ctx.lineCap = 'round'
        ctx.lineJoin = 'round'
        ctx.globalAlpha = opacityRef.current
        // Stroke with background pattern
        if (bgCanvasRef.current) {
          const pattern = ctx.createPattern(bgCanvasRef.current, 'no-repeat')
          if (pattern) {
            // Pattern is in canvas pixel space, but we're scaled by dpr
            // Need to inverse-scale the pattern
            const m = new DOMMatrix()
            m.scaleSelf(1 / dpr, 1 / dpr)
            pattern.setTransform(m)
            ctx.strokeStyle = pattern
          }
        }
        ctx.stroke()
        ctx.restore()
      } else {
        // Normal draw with colour
        ctx.strokeStyle = colourRef.current
        ctx.lineWidth = widthRef.current
        ctx.lineCap = 'round'
        ctx.lineJoin = 'round'
        ctx.globalAlpha = opacityRef.current
        ctx.globalCompositeOperation = blendRef.current
        ctx.stroke()
        ctx.restore()
      }
    }

    // ---- Smudge ----
    const smudge = (x: number, y: number) => {
      const radius = Math.floor(widthRef.current / 2) || 2
      const px = Math.floor(x * dpr)
      const py = Math.floor(y * dpr)
      const d = radius * 2 * dpr
      const sx = Math.max(0, px - radius * dpr)
      const sy = Math.max(0, py - radius * dpr)
      const sw = Math.min(d, canvas.width - sx)
      const sh = Math.min(d, canvas.height - sy)

      if (sw <= 0 || sh <= 0) return

      const current = ctx.getImageData(sx, sy, sw, sh)
      const prev = smudgeBufferRef.current

      if (prev && prev.width === current.width && prev.height === current.height) {
        const strength = opacityRef.current * 0.5
        const data = current.data
        const prevData = prev.data
        for (let i = 0; i < data.length; i += 4) {
          data[i] = data[i] * (1 - strength) + prevData[i] * strength
          data[i + 1] = data[i + 1] * (1 - strength) + prevData[i + 1] * strength
          data[i + 2] = data[i + 2] * (1 - strength) + prevData[i + 2] * strength
        }
        ctx.putImageData(current, sx, sy)
      }

      smudgeBufferRef.current = ctx.getImageData(sx, sy, sw, sh)
    }

    // ---- Event handling ----
    let preStrokeSnapshot: ImageData | null = null

    const startDraw = (x: number, y: number) => {
      const tool = toolRef.current

      // Eyedropper: pick colour and return
      if (tool === 'eyedropper') {
        const px = Math.floor(x * dpr)
        const py = Math.floor(y * dpr)
        const pixel = ctx.getImageData(px, py, 1, 1).data
        const hex = '#' + [pixel[0], pixel[1], pixel[2]]
          .map(v => v.toString(16).padStart(2, '0')).join('')
        colourRef.current = hex
        setActiveColour(hex)
        toolRef.current = 'draw'
        setActiveTool('draw')
        return
      }

      drawingRef.current = true
      pointsRef.current = [{ x, y }]
      preStrokeSnapshot = ctx.getImageData(0, 0, canvas.width, canvas.height)

      if (tool === 'smudge') {
        const radius = Math.floor(widthRef.current / 2) || 2
        const d = radius * 2 * dpr
        const px = Math.floor(x * dpr)
        const py = Math.floor(y * dpr)
        const sx = Math.max(0, px - radius * dpr)
        const sy = Math.max(0, py - radius * dpr)
        const sw = Math.min(d, canvas.width - sx)
        const sh = Math.min(d, canvas.height - sy)
        if (sw > 0 && sh > 0) {
          smudgeBufferRef.current = ctx.getImageData(sx, sy, sw, sh)
        }
      }
    }

    const draw = (x: number, y: number) => {
      if (!drawingRef.current) return
      const tool = toolRef.current

      if (tool === 'smudge') {
        smudge(x, y)
        return
      }

      pointsRef.current.push({ x, y })

      if (preStrokeSnapshot) {
        ctx.putImageData(preStrokeSnapshot, 0, 0)
      }
      redrawStroke()
    }

    const endDraw = () => {
      if (drawingRef.current) {
        preStrokeSnapshot = null
        smudgeBufferRef.current = null
        // Reset composite operation
        ctx.globalCompositeOperation = 'source-over'
        ctx.globalAlpha = 1
        // Save to history
        pushHistory(ctx, canvas)
      }
      drawingRef.current = false
    }

    // Mouse events
    const onMouseDown = (e: MouseEvent) => {
      const { x, y } = getPos(e)
      startDraw(x, y)
    }
    const onMouseMove = (e: MouseEvent) => {
      const { x, y } = getPos(e)
      draw(x, y)
    }
    const onMouseUp = () => endDraw()
    const onMouseLeave = () => endDraw()

    // Touch events
    const onTouchStart = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      if (!touch) return
      const { x, y } = getPos(touch)
      startDraw(x, y)
    }
    const onTouchMove = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      if (!touch) return
      const { x, y } = getPos(touch)
      draw(x, y)
    }
    const onTouchEnd = (e: TouchEvent) => {
      e.preventDefault()
      endDraw()
    }

    // Keyboard shortcuts
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        e.preventDefault()
        if (e.shiftKey) {
          handleRedo()
        } else {
          handleUndo()
        }
      }
    }

    canvas.addEventListener('mousedown', onMouseDown)
    canvas.addEventListener('mousemove', onMouseMove)
    canvas.addEventListener('mouseup', onMouseUp)
    canvas.addEventListener('mouseleave', onMouseLeave)
    canvas.addEventListener('touchstart', onTouchStart, { passive: false })
    canvas.addEventListener('touchmove', onTouchMove, { passive: false })
    canvas.addEventListener('touchend', onTouchEnd, { passive: false })
    window.addEventListener('keydown', onKeyDown)

    return () => {
      ro.disconnect()
      canvas.removeEventListener('mousedown', onMouseDown)
      canvas.removeEventListener('mousemove', onMouseMove)
      canvas.removeEventListener('mouseup', onMouseUp)
      canvas.removeEventListener('mouseleave', onMouseLeave)
      canvas.removeEventListener('touchstart', onTouchStart)
      canvas.removeEventListener('touchmove', onTouchMove)
      canvas.removeEventListener('touchend', onTouchEnd)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [data.photos.nodes, drawBackground, photoKey])

  return (
    <div className="container">
      <Header />

      <div className="particle-draw__hero">
        <Link to="/code" className="back-link">&larr; Back to Code</Link>
        <h1>Photo Draw</h1>
        <p>Draw over photographs &mdash; make something new</p>
        <AccentDots />
      </div>

      <div className="particle-draw__canvas-area">
        <div className="particle-draw__canvas-wrapper" ref={wrapperRef}>
          <canvas
            ref={canvasRef}
            className="particle-draw__canvas"
            style={{
              cursor: activeTool === 'eyedropper' ? 'crosshair'
                : activeTool === 'eraser' ? 'cell'
                : activeTool === 'smudge' ? 'grab'
                : 'crosshair'
            }}
          />
        </div>
        <div className="particle-draw__controls">
          {/* Tools */}
          <div className="particle-draw__tools">
            {([
              { tool: 'draw' as Tool, label: 'Draw' },
              { tool: 'eraser' as Tool, label: 'Eraser' },
              { tool: 'eyedropper' as Tool, label: 'Pick' },
              { tool: 'smudge' as Tool, label: 'Smudge' },
            ]).map(({ tool, label }) => (
              <button
                key={tool}
                className={`particle-draw__tool-btn${activeTool === tool ? ' particle-draw__tool-btn--active' : ''}`}
                onClick={() => handleToolChange(tool)}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Colours */}
          <div className="particle-draw__swatches">
            {SWATCH_COLOURS.map(colour => (
              <button
                key={colour}
                className={`particle-draw__swatch${activeColour === colour ? ' particle-draw__swatch--active' : ''}`}
                style={{ '--swatch-colour': colour } as React.CSSProperties}
                onClick={() => handleColourChange(colour)}
                aria-label={`Select colour ${colour}`}
              />
            ))}
            {/* Show picked colour if it's custom */}
            {!SWATCH_COLOURS.includes(activeColour) && (
              <button
                className="particle-draw__swatch particle-draw__swatch--active"
                style={{ '--swatch-colour': activeColour } as React.CSSProperties}
                aria-label={`Picked colour ${activeColour}`}
              />
            )}
          </div>

          {/* Width */}
          <div className="particle-draw__widths">
            {LINE_WIDTHS.map(w => (
              <button
                key={w}
                className={`particle-draw__width-btn${activeWidth === w ? ' particle-draw__width-btn--active' : ''}`}
                onClick={() => handleWidthChange(w)}
                aria-label={`Line width ${w}px`}
              >
                <span
                  className="particle-draw__width-dot"
                  style={{ width: `${Math.max(w, 4)}px`, height: `${Math.max(w, 4)}px` }}
                />
              </button>
            ))}
          </div>

          {/* Opacity */}
          <div className="particle-draw__opacity">
            <label className="particle-draw__opacity-label">Opacity</label>
            <input
              type="range"
              className="particle-draw__opacity-slider"
              min="0.05"
              max="1"
              step="0.05"
              value={activeOpacity}
              onChange={(e) => {
                const val = parseFloat(e.target.value)
                opacityRef.current = val
                setActiveOpacity(val)
              }}
            />
          </div>

          {/* Blend mode */}
          <div className="particle-draw__blend">
            <select
              className="particle-draw__blend-select"
              value={activeBlend}
              onChange={(e) => handleBlendChange(e.target.value as BlendMode)}
            >
              {BLEND_MODES.map(({ value, label }) => (
                <option key={value} value={value}>{label}</option>
              ))}
            </select>
          </div>

          {/* Undo / Redo */}
          <div className="particle-draw__history">
            <button
              className="particle-draw__clear-btn"
              onClick={handleUndo}
              disabled={!canUndo}
            >
              Undo
            </button>
            <button
              className="particle-draw__clear-btn"
              onClick={handleRedo}
              disabled={!canRedo}
            >
              Redo
            </button>
          </div>

          {/* Actions */}
          <button className="particle-draw__clear-btn" onClick={handleClear}>
            Clear
          </button>
          <button className="particle-draw__clear-btn" onClick={() => setPhotoKey(k => k + 1)}>
            Next Photo
          </button>
          <button className="particle-draw__clear-btn" onClick={() => {
            const canvas = canvasRef.current
            if (!canvas) return
            const link = document.createElement('a')
            link.download = 'photo-draw.png'
            link.href = canvas.toDataURL('image/png')
            link.click()
          }}>
            Save
          </button>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query PhotoDrawQuery {
    photos: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        extension: { regex: "/(jpg|jpeg|png)/" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        childImageSharp {
          original { width height }
          full: gatsbyImageData(
            width: 1200
            placeholder: BLURRED
          )
        }
      }
    }
  }
`

export default ParticleDrawPage
